import Anthropic from '@anthropic-ai/sdk'
import { createClient } from '@supabase/supabase-js'
import { getSystemPrompt } from '@/lib/agents'
import { temAcessoTotal } from '@/lib/permissions/cargos'
import { rateLimit } from '@/lib/rateLimit'

const supabaseAdmin = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!)

export const runtime = 'nodejs'

export async function POST(req: Request) {
  const { agentType, formData, clientId, clientName } = await req.json()
  const token = (req.headers.get('Authorization') || '').replace('Bearer ', '')
  const ip = req.headers.get('x-forwarded-for') || 'unknown'
  if (!rateLimit(ip, 20, 60000)) {
    return Response.json({ error: 'Muitas requisições. Tente novamente em 1 minuto.' }, { status: 429 })
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!
  )

  const { data: { user }, error } = await supabase.auth.getUser(token)
  if (error || !user) return Response.json({ error: 'unauthorized' }, { status: 401 })

  const { data: adv } = await supabase.from('lawyers').select('*').eq('id', user.id).single()

  // Esta rota usa a service role, que ignora RLS. O cargo precisa ser conferido
  // aqui, senão secretária/estagiário geraria peça com o cadastro completo do
  // cliente no prompt. Base sem a coluna `cargo` (migração não aplicada) segue
  // o comportamento anterior.
  if (adv && 'cargo' in adv && !temAcessoTotal(adv.cargo)) {
    return Response.json({ error: 'cargo_sem_permissao' }, { status: 403 })
  }

  const inTrial = new Date(adv.trial_expires_at) > new Date()
  const hasQuota = adv.docs_trial_used < 5
  const isPaid = adv.plan !== 'trial'
  if (!((inTrial && hasQuota) || isPaid)) {
    return Response.json({ error: 'trial_expired' }, { status: 403 })
  }

  const { data: cli } = clientId
    ? await supabase.from('clients').select('*').eq('id', clientId).eq('lawyer_id', user.id).single()
    : { data: null }

  const manualClientName = (clientName || formData?.nome || '').trim()
  if (!clientId && !manualClientName) {
    return Response.json({ error: 'Informe um cliente cadastrado ou o nome manual do cliente.' }, { status: 400 })
  }
  if (clientId && !cli) {
    return Response.json({ error: 'Cliente não encontrado.' }, { status: 400 })
  }

  const resolvedClientId = cli?.id || null
  const resolvedClientName = cli?.name || manualClientName

  const systemPrompt = getSystemPrompt(agentType, adv, cli)
  const anthropic = new Anthropic({ apiKey: process.env.ANTHROPIC_API_KEY })
  const encoder = new TextEncoder()
  let fullText = ''

  const readable = new ReadableStream({
    async start(controller) {
      try {
        const stream = anthropic.messages.stream({
          model: 'claude-sonnet-4-6',
          max_tokens: 6000,
          system: systemPrompt,
          messages: [{ role: 'user', content: JSON.stringify(formData) }],
        })

        for await (const chunk of stream) {
          if (chunk.type === 'content_block_delta' && chunk.delta.type === 'text_delta') {
            fullText += chunk.delta.text
            controller.enqueue(encoder.encode(chunk.delta.text))
          }
        }

        const { data: novoDoc } = await supabase.from('documents').insert({
          lawyer_id: user.id,
          client_id: resolvedClientId,
          client_name: resolvedClientName,
          agent_type: agentType,
          title: formData.nome ? `Petição — ${formData.nome}` : agentType,
          content: fullText,
          form_data: formData,
          status: 'generated',
          lawyer_snapshot: {
            name: adv.name, oab_number: adv.oab_number,
            oab_uf: adv.oab_uf, email: adv.email,
            whatsapp: adv.whatsapp,
            cidade: adv.cidade,
            estado: adv.estado || adv.oab_uf,
            logo_url: adv.logo_url, signature_url: adv.signature_url,
            banner_url: adv.banner_url,
            honorarios_pct: adv.honorarios_pct, vara_padrao: adv.vara_padrao,
            cor_peticao: adv.cor_peticao,
            estilo_peticao: adv.estilo_peticao === 'classico' ? 'classico' : 'moderno',
          }
        }).select('id').single()

        const notificacao = {
          lawyer_id: user.id,
          title: 'Nova petição gerada com sucesso!',
          type: 'success',
        }

        const { error: notifError } = await supabase.from('notifications').insert({
          ...notificacao,
          document_id: novoDoc?.id ?? null,
          status: 'done',
          progress: 100,
        })

        // Fallback para bases onde a migração de document_id/status/progress ainda não foi aplicada
        if (notifError) {
          await supabase.from('notifications').insert(notificacao)
        }

        await supabaseAdmin.from('audit_logs').insert({
          lawyer_id: user.id,
          action: 'GERAR_PETICAO',
          resource: 'documents',
          details: { tipo: formData?.agente || 'petição' },
        })
      } catch (err) {
        controller.enqueue(encoder.encode('[ERRO_GERACAO]'))
      } finally {
        controller.close()
      }
    }
  })

  return new Response(readable, {
    headers: { 'Content-Type': 'text/plain; charset=utf-8' }
  })
}